    const PersonalInfo& getPersonalInfo(uint16_t species, uint8_t form) {
        if (species > PERSONAL_MAX_SPECIES)
            return PERSONAL_INFO_TABLE[0];
        const PersonalInfo& base = PERSONAL_INFO_TABLE[species];
        if (form == 0 || base.formIndex == 0 || form >= base.formCount)
            return base;
        return PERSONAL_INFO_TABLE[base.formIndex + form - 1];
    }
